from bisect import bisect_right

def Sieve(n):
	prime = [True for i in range(n + 1)]
	p = 2
	while p * p <= n:
		if prime[p] == True:
			for i in range(p * p, n + 1, p):
				prime[i] = False
		p += 1
		prime[2] = False
	lst = []
	for p in range(2, n + 1):
		if prime[p]:
			lst.append(p)
	return lst
m = 10 ** 7
val = Sieve(m)
for _ in range(int(input())):
	n = int(input())
	if n == 2:
		print('1')
	else:
		ans = bisect_right(val, n) - bisect_right(val, n // 2)
		print(ans + 1)
